-- == VIDEOJUEGOSZARAGOZA ====================================================
-- Migración: carga de lecciones en el Centro de Aprendizajes
-- Qué hace: apunta en public.aprendizajes las correcciones y normas que el dueño ha dado a
--           Claude entre el 11 y el 14 de octubre de 2026 (hasta ahora solo estaban en la
--           memoria de Claude y en las respuestas). Claude las consulta antes de cada respuesta.
-- Tipo:     solo inserta filas nuevas; si una lección con el mismo título ya existe, no la
--           duplica. No borra ni modifica nada.
-- ============================================================================

insert into public.aprendizajes (titulo, categoria, prioridad, regla, ejemplo_mal, ejemplo_bien)
select v.titulo, v.categoria, v.prioridad, v.regla, v.ejemplo_mal, v.ejemplo_bien
from (values
  ('Formato de respuesta en 7 apartados', 'general', 1,
   'Toda respuesta final va en 7 apartados breves: 1 Resumen, 2 Recomendaciones, 3 Trabajo que queda, 4 Lo que tiene que hacer el dueño (pasos numerados), 5 Repaso de aprendizaje, 6 Permisos especiales utilizados, 7 Modelo recomendado.',
   'Un texto largo sin apartados.', 'Los 7 apartados con viñetas de una línea.'),
  ('Consultar el Centro de Aprendizajes antes de cada respuesta', 'general', 1,
   'Antes de responder o cambiar nada, Claude lee las lecciones activas de esta tabla y las aplica. Cuando el dueño corrige algo o Claude detecta algo que debe aprender, lo apunta aquí él mismo (migración versionada), sin pedírselo al dueño.',
   'Pedir al dueño que guarde la lección a mano.', 'Claude la apunta y lo indica en el apartado 5.'),
  ('Publicar en cuanto la vista previa esté en verde', 'general', 1,
   'Claude publica él mismo con vz-publicar en cuanto Vercel y la revisión automática de GitHub están en verde; el dueño mira los cambios en la app de producción. Solo se reservan al dueño las barreras (infraestructura, .github, .claude), dependencias, scripts, borrados masivos y SQL destructivo.',
   'Pedir al dueño que fusione un cambio de pantalla.', 'Claude fusiona y avisa de que está publicado.'),
  ('Supabase lo aplica Claude', 'general', 1,
   'Claude aplica en Supabase las migraciones ya revisadas y fusionadas en main, aunque cambien permisos. Solo quedan para el dueño: roles, privilegios por defecto, auth.*, vault, cron y lo destructivo, además de las claves en Vercel.',
   'Pedir al dueño que pegue SQL en el SQL Editor desde el móvil cuando Claude podía aplicarlo.', 'Claude aplica la migración y comprueba que las tablas existen.'),
  ('Recomendar modelo en cada respuesta', 'general', 2,
   'Cada respuesta termina con el modelo y esfuerzo recomendados para lo siguiente (tabla en CLAUDE.md, Asesor de modelos); si hay varias tareas, se clasifican una por una para gastar menos tokens.',
   'Usar Opus extra para cambiar un texto.', 'Cambiar el texto del botón: Sonnet 5.5 medio.'),
  ('No inventar datos del negocio', 'negocio', 1,
   'Nunca se inventan garantías, direcciones, precios de envío, plazos ni datos legales: se reutilizan textos reales de la tienda o se pregunta al dueño.',
   'Escribir «1 año de garantía» sin que el dueño lo haya dicho.', 'Usar la frase de garantía que el dueño puso en la descripción del producto.'),
  ('Atención al cliente dentro de la tienda', 'negocio', 1,
   'Todo contacto del cliente va al chat de la tienda: primero responde Blue IA y, si el cliente quiere, pasa al equipo con «Hablar con el equipo». WhatsApp no es la vía principal.',
   'El botón de la ficha abre WhatsApp.', 'El botón de la ficha abre Blue IA con el producto y ofrece hablar con el equipo.'),
  ('Marketing siempre con consentimiento aparte', 'negocio', 1,
   'El permiso de comunicaciones comerciales se pide en una casilla propia y opcional, nunca unido a otra función, y se guarda la fecha en que se acepta o retira.',
   '«Activar avisos (incluye recibir publicidad)».', 'Interruptor de avisos y, aparte, casilla opcional «Acepto recibir ofertas…».'),
  ('Garantías y promesas solo en la descripción', 'textos', 2,
   'En la ficha de producto no se añaden líneas fijas de garantía, revisión o envío: esas promesas las escribe el dueño en la descripción de cada producto.',
   'Tres líneas con iconos de garantía bajo el precio.', 'Precio, botones y debajo la descripción del dueño.'),
  ('Fotos de noticias fieles a la noticia', 'textos', 1,
   'Una noticia solo muestra fotos que enseñan su tema (comprobadas con IA); si no hay ninguna fiable, mejor sin foto.',
   'Noticia de GTA VI con la foto de un supermercado.', 'Carátula o captura del juego, o ninguna foto.'),
  ('Azul de marca en los botones', 'diseno', 1,
   'Los botones principales llevan el azul de marca #1EA7E8 con texto blanco; nunca un azul más oscuro (p. ej. #0E86C4). Paleta: blanco, #1EA7E8 y #0B2138.',
   'Botón «Confirmar pedido» en #0E86C4.', 'Botón «Confirmar pedido» en #1EA7E8.'),
  ('Sin burbujas ni recuadros decorativos', 'diseno', 1,
   'Diseño premium, limpio y minimalista: no se envuelve el contenido en tarjetas o pastillas decorativas; se separan los apartados con espacio y, si hace falta, una línea fina #E3EAF2.',
   'Cada texto metido en un recuadro con borde y fondo.', 'Texto suelto, centrado y con aire entre apartados.'),
  ('Todo centrado', 'diseno', 2,
   'Textos, títulos y botones van centrados en toda la app. Excepciones: burbujas de mensajes del chat, la flecha de volver y los controles ligados al botón de enviar, que van abajo a la derecha encima de él.',
   'Un título pegado a la izquierda.', 'Título y botón centrados; selector del chat encima del botón de enviar.'),
  ('Imágenes enteras, sin recortar', 'diseno', 1,
   'Las imágenes de productos y noticias se muestran completas (contain), con la altura que pide cada foto; en carrusel si hay varias.',
   'Foto recortada para llenar un recuadro fijo.', 'Foto entera con fondo blanco.'),
  ('Precios siempre con céntimos', 'diseno', 2,
   'Todos los precios con dos decimales, coma y punto de miles: 155,00€ y 1.299,00€.',
   '155€', '155,00€'),
  ('Notificaciones dentro de Blue', 'diseno', 2,
   'No hay campanita aparte: las notificaciones son una pestaña del asistente flotante Blue (Asistente, Notificaciones, Noticias).',
   'Campanita y Blue por separado.', 'Panel de Blue con pestañas.'),
  ('Blue fuera del panel', 'panel', 2,
   'El asistente flotante Blue no aparece en ninguna pantalla de administración (ni en los chats de la tienda).',
   'Blue flotando sobre la lista de pedidos del panel.', 'Panel sin Blue.'),
  ('No crear archivos por crear', 'codigo', 1,
   'Lo nuevo se añade a archivos existentes (componentes internos al final de la pantalla, funciones en el archivo más afín). Solo se crea un archivo si no hay ninguno adecuado o lo exige una norma (migraciones, funciones de api/).',
   'Crear components/Seguimientos.tsx para una sección del Perfil.', 'La sección dentro de app/(tabs)/perfil.tsx.'),
  ('Comandos sin ventanas de permiso', 'codigo', 1,
   'Un comando simple por llamada; rutas con paréntesis o corchetes siempre entre comillas; nunca find -exec ni xargs; nunca tocar ~/.claude (ni las imágenes subidas) con Bash: las imágenes se miran con Read.',
   'grep -n X app/(tabs)/cesta.tsx', 'grep -n X «app/(tabs)/cesta.tsx» con comillas dobles.'),
  ('Comprobar errores de código en todas las ramas', 'codigo', 1,
   'Toda rama pasa tsc antes de subirse, aunque solo cambie un texto o api/. Dentro de un texto entre comillas dobles se usan «».',
   'Comillas dobles dentro de un texto entre comillas dobles (rompió Blue IA).', 'Usar «Hablar con el equipo» dentro del texto.'),
  ('Funciones del servidor en api/', 'codigo', 1,
   'En Vercel las funciones del servidor van en la carpeta api/ en minúsculas; si algo del servidor no responde, lo primero es mirar los registros de Vercel.',
   'aPI/blue-ia.ts', 'api/blue-ia.ts'),
  ('Ramas desde main actualizado y volver a main', 'codigo', 1,
   'Antes de crear una rama: git fetch origin main. Al terminar cada tarea (y siempre antes de pedir sudo vz-instalar-claude): dejar la copia en main igual a origin/main, o el instalador se para.',
   'Pedir la instalación con la copia en una rama de trabajo.', 'git switch main y git pull --ff-only, luego pedir la instalación.'),
  ('Lo que usa el código tiene que existir en la base de datos', 'codigo', 2,
   'Antes de dar por buena una función se comprueba que existen en Supabase sus tablas, columnas y funciones; los archivos antiguos de sql/ puede que nunca se aplicaran.',
   'La portada pide product_sales y la tabla no existe.', 'Crear la tabla con una migración y comprobar en los registros que el error desaparece.'),
  ('Revisar los registros de errores', 'codigo', 2,
   'Al revisar la tienda se miran los errores de Supabase y de Vercel, no solo si las páginas abren.',
   'Dar la tienda por buena porque todas las páginas responden.', 'Encontrar en los registros que la portada pide una tabla que no existe.'),
  ('Toque y arrastre separados', 'codigo', 2,
   'En un elemento que se toca y se arrastra, el toque va con un Pressable y el arrastre solo empieza cuando el dedo se mueve (si no, en Safari del iPhone no responde).',
   'Detectar el toque con el mismo PanResponder del arrastre.', 'Pressable para tocar y arrastre a partir de unos píxeles.'),
  ('Archivos de ayuda fuera de app/', 'codigo', 3,
   'En app/ solo van pantallas; tipos, utilidades y componentes comunes van en lib/ o components/, porque en app/ se publican como páginas vacías.',
   'app/admin/products/products.utils.ts', 'lib/admin/products.utils.ts'),
  ('Nombres y valores de variables secretas', 'codigo', 3,
   'Las variables con claves usan nombres en español (el controlador confunde SERVICE_ROLE con una clave) y sus valores solo letras sin ñ ni tildes, números y símbolos normales.',
   'CRON_SECRET con una ñ.', 'SUPABASE_CLAVE_SERVIDOR y CRON_SECRET con letras A-Z y números.'),
  ('Formularios públicos sin campos del taller', 'seguridad', 1,
   'Los formularios que puede enviar cualquiera no aceptan del visitante datos internos (estado, notas del admin, etapas): la base de datos los fuerza a su valor inicial.',
   'Una solicitud de reparación enviada ya como «entregado».', 'Toda solicitud nueva entra como «nuevo» o «solicitado».')
) as v(titulo, categoria, prioridad, regla, ejemplo_mal, ejemplo_bien)
where not exists (select 1 from public.aprendizajes a where a.titulo = v.titulo);
